import { RejectedCandidate } from "@/components/cockpit/rejected-candidate"
import type {
  Candidate,
  CandidateState,
} from "@/components/cockpit/candidate-types"
import { Button } from "@/components/ui/button"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { CALLS, CANDIDATES, LANDED_LINES, SCRIPT } from "@/lib/case-001"
import { cn } from "@/lib/utils"

export function CandidatePanel({
  visible,
  currentStepId,
  chosenCandidateIds,
  decisionRecorded,
  onClose,
}: {
  visible: number
  currentStepId: string | null
  chosenCandidateIds: readonly string[]
  decisionRecorded: boolean
  onClose: () => void
}) {
  const visibleIds = new Set(SCRIPT.slice(0, visible).map((step) => step.id))
  const state: CandidateState = {
    candidatesVisible: visibleIds.has("suppliers"),
    policyComplete: visibleIds.has("policy"),
    outreachStarted: visibleIds.has("outreach"),
    claimsComplete: visibleIds.has("claims"),
    costsComplete: visibleIds.has("deltas"),
    decisionRecorded,
  }
  const candidates = state.candidatesVisible ? CANDIDATES : []

  return (
    <aside
      aria-label="Candidates"
      className="flex h-full w-full min-w-0 flex-col overflow-hidden bg-sidebar text-foreground"
    >
      <header className="flex min-h-11 shrink-0 items-center justify-between border-b border-border px-3">
        <h2 className="text-sm font-medium">Candidates</h2>
        <Button
          type="button"
          size="icon-sm"
          variant="ghost"
          aria-label="Close Candidates sidebar"
          onClick={onClose}
        >
          <XIcon aria-hidden="true" />
        </Button>
      </header>
      {candidates.length === 0 ? (
        <p className="p-4 text-sm text-muted-foreground">
          No Candidates matched yet.
        </p>
      ) : (
        <div className="min-h-0 flex-1 overflow-y-auto">
          {candidates.map((candidate, index) => (
            <CandidateRow
              key={candidate.name}
              candidate={candidate as Candidate}
              state={state}
              visibleIds={visibleIds}
              currentStepId={currentStepId}
              chosen={chosenCandidateIds.includes(candidate.id)}
              agentIndex={index}
            />
          ))}
        </div>
      )}
    </aside>
  )
}

function CandidateRow({
  candidate,
  state,
  visibleIds,
  currentStepId,
  chosen,
  agentIndex,
}: {
  candidate: Candidate
  state: CandidateState
  visibleIds: ReadonlySet<string>
  currentStepId: string | null
  chosen: boolean
  agentIndex: number
}) {
  const rejected = state.policyComplete && candidate.compliance === "failed"
  const call = CALLS.find(
    (item) => item.candidateId === candidate.id && visibleIds.has(item.afterId)
  )
  const landedLine = LANDED_LINES.find(
    (line) => line.candidateId === candidate.id
  )
  const status = candidateLifecycleStatus({
    candidate,
    state,
    call,
    landedLine,
    chosen: state.decisionRecorded && chosen,
  })
  const description = candidate.supplierRecord.preferred
    ? `${candidate.country} · Preferred Supplier Record`
    : `${candidate.country} · Supplier Record`

  return (
    <Collapsible className="border-b border-border">
      <CollapsibleTrigger className="group flex min-h-9 w-full items-center gap-2 px-2.5 pt-1.5 pb-1 text-left outline-none hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset">
        <span className="min-w-0 flex-1">
          <span className="block truncate text-xs font-medium">
            {candidate.name}
          </span>
          <span className="block truncate text-[11px] leading-4 text-muted-foreground">
            {description}
          </span>
        </span>
        <LifecycleStatus status={status} />
        <ChevronDownIcon
          aria-hidden="true"
          className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-200 ease-[cubic-bezier(0.77,0,0.175,1)] group-data-[panel-open]:rotate-180 motion-reduce:transition-none"
        />
      </CollapsibleTrigger>
      {call ? (
        <CallingAgentCard
          call={call}
          currentStepId={currentStepId}
          claimsComplete={state.claimsComplete}
          index={agentIndex}
        />
      ) : null}
      <CollapsibleContent>
        <div className="border-t border-border bg-background/50 px-3 py-2.5">
          {rejected ? (
            <RejectedCandidate candidate={candidate} />
          ) : (
            <CandidateComparison
              candidate={candidate}
              state={state}
              call={call}
              landedLine={landedLine}
            />
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

const STATUS_STYLES: Record<
  CandidateLifecycleStatus,
  { className: string; dotClassName: string }
> = {
  sourced: {
    className: "bg-muted-foreground/20 text-foreground",
    dotClassName: "bg-muted-foreground",
  },
  "no answer": {
    className: "bg-muted-foreground/20 text-foreground",
    dotClassName: "bg-muted-foreground",
  },
  incomplete: {
    className: "bg-chart-1/30 text-foreground",
    dotClassName: "bg-chart-1",
  },
  ready: {
    className: "bg-chart-5/30 text-foreground",
    dotClassName: "bg-chart-5",
  },
  chosen: {
    className: "bg-primary/30 text-foreground",
    dotClassName: "bg-primary",
  },
  rejected: {
    className: "bg-destructive/30 text-foreground",
    dotClassName: "bg-destructive",
  },
}

function LifecycleStatus({ status }: { status: CandidateLifecycleStatus }) {
  const style = STATUS_STYLES[status]

  return (
    <span
      className={cn(
        "inline-flex h-4.5 shrink-0 items-center gap-1 rounded-full px-1.5 text-[10px] font-medium",
        style.className
      )}
    >
      <span
        aria-hidden="true"
        className={cn("size-2 rounded-full", style.dotClassName)}
      />
      {status}
    </span>
  )
}

const AGENT_NAMES = ["Mara", "Oskar", "Nia", "Felix", "Liv", "Theo"]
const AGENT_AVATAR_STYLES = [
  "bg-chart-1/30 text-chart-1",
  "bg-chart-2/30 text-chart-2",
  "bg-chart-3/30 text-chart-3",
  "bg-chart-4/30 text-chart-4",
  "bg-chart-5/30 text-chart-5",
]

function CallingAgentCard({
  call,
  currentStepId,
  claimsComplete,
  index,
}: {
  call: (typeof CALLS)[number]
  currentStepId: string | null
  claimsComplete: boolean
  index: number
}) {
  const router = useRouter()
  const profile = agentProfile(call.candidateId)
  const status = agentCallStatus(call, currentStepId, claimsComplete, index)
  const delay = `${Math.min(index, 3) * 140}ms`

  function openCall() {
    const nextParams = new URLSearchParams(window.location.search)
    nextParams.set("call", call.id)
    router.replace(`${window.location.pathname}?${nextParams.toString()}`, {
      scroll: false,
    })
  }

  return (
    <div
      className="candidate-agent-reveal grid px-2.5"
      style={{ "--agent-delay": delay } as CSSProperties}
    >
      <div className="min-h-0 overflow-hidden">
        <button
          type="button"
          className="candidate-agent-card mb-1.5 flex w-full items-center gap-2 rounded-full bg-background/60 p-1 pr-2 text-left outline-none transition-colors duration-150 hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring"
          onClick={openCall}
          aria-label={`Open ${profile.name}'s call with ${call.supplier}`}
        >
          <Avatar size="sm" className="after:border-0">
            <AvatarFallback className={profile.avatarClassName}>
              <Bot aria-hidden="true" className="size-3.5" />
            </AvatarFallback>
          </Avatar>
          <span className="min-w-0 flex-1 truncate text-xs font-medium">
            {profile.name}
          </span>
          <span className="shrink-0 text-[11px] text-muted-foreground tabular-nums">
            {status}
          </span>
        </button>
      </div>
    </div>
  )
}

function agentProfile(candidateId: string) {
  const hash = [...candidateId].reduce(
    (value, character) => (value * 31 + character.charCodeAt(0)) >>> 0,
    7
  )

  return {
    name: AGENT_NAMES[hash % AGENT_NAMES.length],
    avatarClassName:
      AGENT_AVATAR_STYLES[
        Math.floor(hash / AGENT_NAMES.length) % AGENT_AVATAR_STYLES.length
      ],
  }
}

function agentCallStatus(
  call: (typeof CALLS)[number],
  currentStepId: string | null,
  claimsComplete: boolean,
  index: number
) {
  if (claimsComplete) {
    if (call.status === "no_answer") return "no answer"
    if (call.status === "stopped_for_human") return "stopped"
    return call.duration
  }
  if (currentStepId === "claims") return "calling..."
  return index < 2 ? "calling..." : "dialing..."
}
