}: {
  agentRuns: readonly CallingAgentRun[]
}) {
  const router = useRouter()
  const completedRuns = [...agentRuns]
    .filter((agent) => agent.phase === "complete")
    .sort(
      (left, right) => (left.completedAt ?? 0) - (right.completedAt ?? 0)
    )

  function openCall(callId: string) {
