import { CALLS } from "@/lib/case-001/calls"

export type CallingAgentPhase = "queued" | "dialing" | "calling" | "complete"

export type CallingAgentPlan = {
  callId: string
  candidateId: string
  name: string
  avatarClassName: string
  launchDelayMs: number
  dialingMs: number
  durationMs: number
}

export type CallingAgentRun = CallingAgentPlan & {
  phase: CallingAgentPhase
  elapsedMs: number
  startedAt: number | null
  completedAt: number | null
  durationLabel: string
  visibleTranscriptTurnCount: number
}

const AGENT_NAMES = [
  "Mara",
  "Oskar",
  "Nia",
  "Felix",
  "Liv",
  "Theo",
  "Anika",
  "Jules",
]

const AGENT_AVATAR_STYLES = [
  "bg-chart-1/30 text-chart-1",
  "bg-chart-2/30 text-chart-2",
  "bg-chart-3/30 text-chart-3",
  "bg-chart-4/30 text-chart-4",
  "bg-chart-5/30 text-chart-5",
]

export const INITIAL_CALLING_AGENT_PLAN: readonly CallingAgentPlan[] =
  CALLS.map((call, index) => ({
    callId: call.id,
    candidateId: call.candidateId,
    name: AGENT_NAMES[index],
    avatarClassName: AGENT_AVATAR_STYLES[index],
    launchDelayMs: 400 + index * 180,
    dialingMs: 2400,
    durationMs: 18000 + index * 5000,
  }))

export function createCallingAgentPlan(): readonly CallingAgentPlan[] {
  const names = shuffled(AGENT_NAMES)

  return CALLS.map((call, index) => ({
    callId: call.id,
    candidateId: call.candidateId,
    name: names[index],
    avatarClassName:
      AGENT_AVATAR_STYLES[randomInteger(0, AGENT_AVATAR_STYLES.length - 1)],
    launchDelayMs: randomInteger(250, 1200),
    dialingMs: randomInteger(1800, 4200),
    durationMs: randomInteger(15000, 45000),
  }))
}

export function resolveCallingAgentRuns(
  plan: readonly CallingAgentPlan[],
  startedAtByCall: Readonly<Record<string, number>>,
  now: number
): readonly CallingAgentRun[] {
  return plan.map((agent) => {
    const requestedAt = startedAtByCall[agent.callId]
    if (requestedAt === undefined) return queuedRun(agent)

    const startedAt = requestedAt + agent.launchDelayMs
    const elapsedMs = Math.max(0, Math.min(now - startedAt, agent.durationMs))
    const completed = elapsedMs >= agent.durationMs
    const phase: CallingAgentPhase =
      now < startedAt
        ? "queued"
        : completed
          ? "complete"
          : elapsedMs < agent.dialingMs
            ? "dialing"
            : "calling"

    return {
      ...agent,
      phase,
      elapsedMs,
      startedAt,
      completedAt: completed ? startedAt + agent.durationMs : null,
      durationLabel: formatCallDuration(elapsedMs),
      visibleTranscriptTurnCount: transcriptTurnCount(agent, elapsedMs, phase),
    }
  })
}

export function latestCallingAgentEnd(
  plan: readonly CallingAgentPlan[],
  startedAtByCall: Readonly<Record<string, number>>
) {
  return Math.max(
    0,
    ...plan.flatMap((agent) => {
      const requestedAt = startedAtByCall[agent.callId]
      return requestedAt === undefined
        ? []
        : [requestedAt + agent.launchDelayMs + agent.durationMs]
    })
  )
}

export function formatCallDuration(milliseconds: number) {
  const totalSeconds = Math.max(0, Math.floor(milliseconds / 1000))
  const minutes = Math.floor(totalSeconds / 60)
  const seconds = String(totalSeconds % 60).padStart(2, "0")
  return `${minutes}:${seconds}`
}

function queuedRun(agent: CallingAgentPlan): CallingAgentRun {
  return {
    ...agent,
    phase: "queued",
    elapsedMs: 0,
    startedAt: null,
    completedAt: null,
    durationLabel: "0:00",
    visibleTranscriptTurnCount: 0,
  }
}

function transcriptTurnCount(
  agent: CallingAgentPlan,
  elapsedMs: number,
  phase: CallingAgentPhase
) {
  if (phase === "queued" || phase === "dialing") return 0
  const call = CALLS.find((item) => item.id === agent.callId)
  const turnCount = call?.transcript.length ?? 0
  if (phase === "complete") return turnCount

  const speakingMs = Math.max(1, agent.durationMs - agent.dialingMs)
  const progress = Math.max(0, (elapsedMs - agent.dialingMs) / speakingMs)
  return Math.max(1, Math.min(turnCount, Math.ceil(progress * turnCount)))
}

function shuffled<T>(values: readonly T[]): T[] {
  const result = [...values]
  for (let index = result.length - 1; index > 0; index -= 1) {
    const target = randomInteger(0, index)
    ;[result[index], result[target]] = [result[target], result[index]]
  }
  return result
}

function randomInteger(minimum: number, maximum: number) {
  const range = maximum - minimum + 1
  const values = new Uint32Array(1)
  crypto.getRandomValues(values)
  return minimum + (values[0] % range)
}
import { useCallback, useEffect, useState } from "react"

import {
  createCallingAgentPlan,
  getStepResponse,
  INITIAL_CALLING_AGENT_PLAN,
  latestCallingAgentEnd,
  resolveCallingAgentRuns,
  SCRIPT,
  STEP_SETTLE_DELAY_MS,
  STREAM_CHARS_PER_TICK,
  STREAM_TICK_MS,
} from "@/lib/case-001"

type PlaybackPhase = "waiting" | "text"
type PlaybackStatus = "streaming" | "stopped" | "complete"
type RehearsalTurnPhase = "pending" | "streaming" | "stopped" | "complete"

type PlaybackState = {
  status: PlaybackStatus
  phase: PlaybackPhase
  stepIndex: number
  text: string
}

const INITIAL_STATE: PlaybackState = {
  status: "streaming",
  phase: "waiting",
  stepIndex: 0,
  text: "",
}

// This hook is the timer-driven replacement seam for a live Devin Session.
// Keep its contract small so the Cockpit can later consume server events instead.
export function useDeterministicRehearsal() {
  const [playback, setPlayback] = useState<PlaybackState>(INITIAL_STATE)
  const [agentPlan, setAgentPlan] = useState(INITIAL_CALLING_AGENT_PLAN)
  const [agentStartedAt, setAgentStartedAt] = useState<Record<string, number>>(
    {}
  )
  const [clock, setClock] = useState(0)

  useEffect(() => {
    const timeout = window.setTimeout(() => {
      setAgentPlan(createCallingAgentPlan())
    }, 0)

    return () => window.clearTimeout(timeout)
  }, [])

  useEffect(() => {
    const step = SCRIPT[playback.stepIndex]
    if (
      playback.status !== "streaming" ||
      step?.kind !== "outreach" ||
      !step.callId ||
      agentStartedAt[step.callId] !== undefined
    ) {
      return
    }

    const callId = step.callId
    const timeout = window.setTimeout(() => {
      const startedAt = Date.now()
      setAgentStartedAt((current) => ({
        ...current,
        [callId]: startedAt,
      }))
      setClock(startedAt)
    }, 0)

    return () => window.clearTimeout(timeout)
  }, [agentStartedAt, playback.status, playback.stepIndex])

  useEffect(() => {
    if (
      playback.status !== "streaming" ||
      Object.keys(agentStartedAt).length === 0
    ) {
      return
    }

    const endAt = latestCallingAgentEnd(agentPlan, agentStartedAt)
    const updateClock = () => {
      const now = Date.now()
      setClock(now)
      return now >= endAt
    }

    if (updateClock()) return
    const interval = window.setInterval(() => {
      if (updateClock()) window.clearInterval(interval)
    }, 250)

    return () => window.clearInterval(interval)
  }, [agentPlan, agentStartedAt, playback.status])

  useEffect(() => {
    if (playback.status !== "streaming") return

    const step = SCRIPT[playback.stepIndex]
    if (!step) return

    if (playback.phase === "waiting") {
      const waitMs =
        step.id === "claims" &&
        agentPlan.every((agent) => agentStartedAt[agent.callId] !== undefined)
          ? Math.max(
              0,
              latestCallingAgentEnd(agentPlan, agentStartedAt) - Date.now()
            )
          : step.waitMs
      const timeout = window.setTimeout(() => {
        setPlayback((current) => {
          if (
            current.status !== "streaming" ||
            current.phase !== "waiting" ||
            current.stepIndex !== playback.stepIndex
          ) {
            return current
          }

          return { ...current, phase: "text", text: "" }
        })
      }, waitMs)

      return () => window.clearTimeout(timeout)
    }

    const response = getStepResponse(step)
    if (playback.text.length < response.length) {
      const timeout = window.setTimeout(() => {
        setPlayback((current) => {
          if (
            current.status !== "streaming" ||
            current.phase !== "text" ||
            current.stepIndex !== playback.stepIndex
          ) {
            return current
          }

          const nextLength = Math.min(
            current.text.length + STREAM_CHARS_PER_TICK,
            response.length
          )
          return { ...current, text: response.slice(0, nextLength) }
        })
      }, STREAM_TICK_MS)

      return () => window.clearTimeout(timeout)
    }

    const timeout = window.setTimeout(() => {
      setPlayback((current) => {
        if (
          current.status !== "streaming" ||
          current.phase !== "text" ||
          current.stepIndex !== playback.stepIndex
        ) {
          return current
        }

        const nextStepIndex = current.stepIndex + 1
        if (nextStepIndex === SCRIPT.length) {
          return {
            status: "complete",
            phase: "waiting",
            stepIndex: nextStepIndex,
            text: "",
          }
        }

        return {
          status: "streaming",
          phase: "waiting",
          stepIndex: nextStepIndex,
          text: "",
        }
      })
    }, STEP_SETTLE_DELAY_MS)

    return () => window.clearTimeout(timeout)
  }, [agentPlan, agentStartedAt, playback])

  const stop = useCallback(() => {
    setPlayback((current) => {
      if (current.status !== "streaming") return current
      return { ...current, status: "stopped" }
    })
  }, [])

  const replay = useCallback(() => {
    setAgentPlan(createCallingAgentPlan())
    setAgentStartedAt({})
    setClock(0)
    setPlayback(INITIAL_STATE)
  }, [])

  const currentStepIndex =
    playback.status === "streaming" ||
    (playback.status === "stopped" && playback.phase === "text")
      ? playback.stepIndex
      : null
  const currentPhase: RehearsalTurnPhase | null =
    currentStepIndex === null
      ? null
      : playback.status === "stopped"
        ? "stopped"
        : playback.phase === "waiting"
          ? "pending"
          : playback.text === getStepResponse(SCRIPT[playback.stepIndex])
            ? "complete"
            : "streaming"
  const revealedSteps =
    playback.status === "complete"
      ? SCRIPT.length
      : playback.stepIndex + (playback.phase === "text" ? 1 : 0)
  const agentRuns = resolveCallingAgentRuns(
    agentPlan,
    agentStartedAt,
    clock || Math.max(0, ...Object.values(agentStartedAt))
  )

  return {
    completedSteps: playback.stepIndex,
    currentPhase,
    currentStepIndex,
    currentText: playback.text,
    agentRuns,
    revealedSteps,
    running: playback.status === "streaming",
    replay,
    stop,
  }
}
"use client"

import { useRouter } from "next/navigation"

import { Bot } from "@/components/icons"
import { DotLoader } from "@/components/cockpit/dot-loader"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { CALLS, type CallingAgentRun } from "@/lib/case-001"

export function AgentCallActivity({
  agentRuns,
}: {
  agentRuns: readonly CallingAgentRun[]
}) {
  const router = useRouter()
  const visibleRuns = [...agentRuns]
    .filter((agent) => agent.phase !== "queued")
    .sort((left, right) => (left.startedAt ?? 0) - (right.startedAt ?? 0))

  function openCall(callId: string) {
    const nextParams = new URLSearchParams(window.location.search)
    nextParams.set("call", callId)
    router.replace(`${window.location.pathname}?${nextParams.toString()}`, {
      scroll: false,
    })
  }

  if (visibleRuns.length === 0) return null

  return (
    <div className="grid gap-1" aria-label="Calling agents">
      {visibleRuns.map((agent) => {
        const call = CALLS.find((item) => item.id === agent.callId)
        if (!call) return null
        const complete = agent.phase === "complete"

        return (
          <button
            key={agent.callId}
            type="button"
            className="agent-inline-call group flex w-full items-start gap-2 rounded-lg px-2 py-1.5 text-left outline-none hover:bg-muted/60 focus-visible:ring-2 focus-visible:ring-ring"
            data-complete={complete}
            onClick={() => openCall(agent.callId)}
            aria-label={`Open ${complete ? "completed" : "active"} call with ${call.supplier}`}
          >
            <Avatar size="sm" className="mt-0.5 after:border-0">
              <AvatarFallback className={agent.avatarClassName}>
                <Bot aria-hidden="true" className="size-3.5" />
              </AvatarFallback>
            </Avatar>
            <span className="min-w-0 flex-1">
              <span className="flex items-baseline gap-1.5 text-xs">
                <span className="truncate font-medium">{agent.name}</span>
                {!complete ? <DotLoader className="size-3.5" /> : null}
                <span className="shrink-0 text-muted-foreground tabular-nums">
                  · {agent.durationLabel}
                </span>
              </span>
              <span className="mt-0.5 block truncate text-[11px] text-muted-foreground">
                {complete
                  ? `Completed · Claim filed for ${call.supplier}`
                  : agent.phase === "dialing"
                    ? `Dialing ${call.supplier}...`
                    : `Calling ${call.supplier}...`}
              </span>
            </span>
          </button>
        )
      })}
    </div>
  )
}
"use client"

import { useState } from "react"

import { CheckIcon, ChevronRightIcon } from "@/components/icons"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { CANDIDATES, LANDED_LINES } from "@/lib/case-001"
import { cn } from "@/lib/utils"

type DecisionBarProps = {
  recorded: boolean
  selectedCandidateId: string | null
  onSelectCandidate: (candidateId: string) => void
  onRecord: () => void
}

const SELECTABLE_CANDIDATES = CANDIDATES.filter((candidate) => {
  const landedLine = LANDED_LINES.find(
    (line) => line.candidateId === candidate.id
  )
  return candidate.compliance === "passed" && landedLine?.usable !== false
})

export function DecisionBar({
  recorded,
  selectedCandidateId,
  onSelectCandidate,
  onRecord,
}: DecisionBarProps) {
  const [open, setOpen] = useState(false)
  const selectedCandidate = CANDIDATES.find(
    (candidate) => candidate.id === selectedCandidateId
  )

  function recordDecision() {
    onRecord()
    setOpen(false)
  }

  return (
    <div className="mx-auto w-full max-w-[50vw] px-4 pt-3">
      <Collapsible open={open} onOpenChange={setOpen}>
        <Card
          size="sm"
          className="w-full gap-0 border border-border bg-secondary/70 py-0 ring-0"
        >
          <CollapsibleContent className="border-b border-border/70 px-3 py-3">
            <DecisionDetails
              recorded={recorded}
              selectedCandidateId={selectedCandidateId}
              onSelectCandidate={onSelectCandidate}
              onRecord={recordDecision}
            />
          </CollapsibleContent>
          <CollapsibleTrigger
            className="group flex min-h-10 w-full min-w-0 items-center gap-3 px-3 py-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring"
            aria-label="Toggle Decision details"
          >
            <span className="text-sm font-medium">Complete</span>
            <span className="ml-auto flex min-w-0 items-center gap-1 text-sm text-muted-foreground">
              {recorded ? (
                <>
                  <CheckIcon aria-hidden="true" className="size-3.5" />
                  <span className="truncate">
                    {selectedCandidate?.name ?? "Decision recorded"}
                  </span>
                </>
              ) : (
                <span>Take decision</span>
              )}
              <ChevronRightIcon className="size-4 shrink-0 transition-transform duration-200 ease-[cubic-bezier(0.77,0,0.175,1)] group-data-[panel-open]:rotate-90 motion-reduce:transition-none" />
            </span>
          </CollapsibleTrigger>
        </Card>
      </Collapsible>
    </div>
  )
}

function DecisionDetails({
  recorded,
  selectedCandidateId,
  onSelectCandidate,
  onRecord,
}: DecisionBarProps) {
  return (
    <div className="text-sm">
      <p className="font-medium">Choose a Candidate</p>
      <p className="mt-1 text-xs text-muted-foreground">
        Compare Claims and Supplier Records before you record the Decision.
      </p>
      <div className="mt-3 grid gap-1.5" role="radiogroup">
        {SELECTABLE_CANDIDATES.map((candidate) => {
          const selected = selectedCandidateId === candidate.id
          const landedLine = LANDED_LINES.find(
            (line) => line.candidateId === candidate.id
          )

          return (
            <button
              key={candidate.id}
              type="button"
              role="radio"
              aria-checked={selected}
              disabled={recorded}
              className={cn(
                "flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left transition-colors duration-150 outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-default",
                selected ? "bg-secondary" : "hover:bg-muted/70"
              )}
              onClick={() => onSelectCandidate(candidate.id)}
            >
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-4 shrink-0 items-center justify-center rounded-full border",
                  selected
                    ? "border-foreground bg-foreground text-background"
                    : "border-muted-foreground/50"
                )}
              >
                {selected ? <CheckIcon className="size-3" /> : null}
              </span>
              <span className="min-w-0 flex-1">
                <span className="block truncate text-xs font-medium">
                  {candidate.name}
                </span>
                <span className="block truncate text-[11px] text-muted-foreground">
                  {candidate.claimUnit} · {landedLine?.arrivalDays ?? "unknown"}{" "}
                  days
                </span>
              </span>
              <Badge variant="secondary">ready</Badge>
            </button>
          )
        })}
      </div>
      <Button
        type="button"
        size="lg"
        className="mt-4 w-full rounded-xl bg-foreground text-background hover:bg-foreground/85"
        disabled={!selectedCandidateId || recorded}
        onClick={onRecord}
      >
        {recorded ? "Decision recorded" : "Record Decision"}
      </Button>
      <p className="mt-2 text-[11px] text-muted-foreground">
        Recording is final. It does not place an order.
      </p>
    </div>
  )
}

